import{_ as a,o as t,c as o,a0 as r}from"./chunks/framework.DqMqoJl9.js";const l="/assets/12-greedy-algorithm_20210603170858.B86ss3F3.png",d="/assets/12-greedy-algorithm_20210603171122.BY0xy6LS.png",g=JSON.parse('{"title":"贪心算法","description":"","frontmatter":{},"headers":[],"relativePath":"algorithm/12-greedy-algorithm.md","filePath":"algorithm/12-greedy-algorithm.md","lastUpdated":1791573371000}'),i={name:"algorithm/12-greedy-algorithm.md"};function c(h,e,s,n,_,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="贪心算法" tabindex="-1">贪心算法 <a class="header-anchor" href="#贪心算法" aria-label="Permalink to &quot;贪心算法&quot;">​</a></h1><h2 id="_1-概念" tabindex="-1">1 概念 <a class="header-anchor" href="#_1-概念" aria-label="Permalink to &quot;1 概念&quot;">​</a></h2><ul><li>贪心算法是算法设计中的一种方法</li><li>期盼通过 <code>每个阶段</code> 的局部最优选择，从而达到全局的最优</li><li>贪心算法结果不一定是最优的</li></ul><h3 id="_1-1-例子" tabindex="-1">1.1 例子 <a class="header-anchor" href="#_1-1-例子" aria-label="Permalink to &quot;1.1 例子&quot;">​</a></h3><p>假设我们有一个可以容纳 100kg 物品的背包，可以装各种物品。我们有以下 5 种豆子，每种豆子的总量和总价值都各不相同。为了让背包中所装物品的总价值最大，我们如何选择在背包中装哪些豆子？每种豆子又该装多少呢？</p><p><img src="'+l+'" alt=""></p><blockquote><p>我们只要先算一算每个物品的单价，按照单价由高到低依次来装就好了。这个思路就是贪心算法</p></blockquote><h3 id="_1-2-结果不一定最优" tabindex="-1">1.2 结果不一定最优 <a class="header-anchor" href="#_1-2-结果不一定最优" aria-label="Permalink to &quot;1.2 结果不一定最优&quot;">​</a></h3><p>在一个有权图中，我们从顶点 S 开始，找一条到顶点 T 的最短路径（路径中边的权值和最小）</p><p><img src="'+d+'" alt=""></p><p>贪心算法的解决思路是，每次都选择一条跟当前顶点相连的权最小的边，直到找到顶点 T</p><p>求出的最短路径是 <code>S-&gt;A-&gt;E-&gt;T</code>，路径长度是 <code>1+4+4=9</code>。最终求的路径并不是最短路径，因为路径 <code>S-&gt;B-&gt;D-&gt;T</code> 才是最短路径，因为这条路径的长度是 <code>2+2+2=6</code></p><blockquote><p>在这个问题上，贪心算法不工作的主要原因是，前面的选择，会影响后面的选择</p></blockquote><h2 id="_2-leetcode" tabindex="-1">2 LeetCode <a class="header-anchor" href="#_2-leetcode" aria-label="Permalink to &quot;2 LeetCode&quot;">​</a></h2><h3 id="_2-1-leetcode-455-分饼干" tabindex="-1">2.1 LeetCode 455 分饼干 <a class="header-anchor" href="#_2-1-leetcode-455-分饼干" aria-label="Permalink to &quot;2.1 LeetCode 455 分饼干&quot;">​</a></h3><h3 id="_2-2-leetcode-122-买卖股票的最佳时机-ii" tabindex="-1">2.2 LeetCode 122 买卖股票的最佳时机 II <a class="header-anchor" href="#_2-2-leetcode-122-买卖股票的最佳时机-ii" aria-label="Permalink to &quot;2.2 LeetCode 122 买卖股票的最佳时机 II&quot;">​</a></h3>',16)])])}const u=a(i,[["render",c]]);export{g as __pageData,u as default};
